import React, { useState, useEffect } from 'react';
import { dashboardApi } from '../api/client';
import SkeletonCard from './SkeletonCard';
import EmptyState from './EmptyState';
import { Activity } from 'lucide-react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler,
} from 'chart.js';
import { Line } from 'react-chartjs-2';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler
);

const HealthTrendChart = () => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchHealthTrend();
  }, []);

  const fetchHealthTrend = async () => {
    try {
      setLoading(true);
      const res = await dashboardApi.getHealthTrend();
      if (res.data.success) {
        setData(res.data.data);
      }
    } catch (err) {
      console.error('Failed to fetch health trend:', err);
    } finally {
      setLoading(false);
    }
  };

  if (loading) return <SkeletonCard height="300px" />;
  if (!data || data.length === 0) {
    return (
      <div className="glass-card" style={{ padding: '1.5rem' }}>
        <h3 style={{ fontSize: '1.05rem', fontWeight: '700', marginBottom: '1rem', color: 'var(--text-primary)' }}>
          Machine Health Trend
        </h3>
        <EmptyState title="No Health Trend Data" message="Unable to load 7-day health trend." />
      </div>
    );
  }

  const chartData = {
    labels: data.map((d) => d.date),
    datasets: [
      {
        label: 'Fleet Health Score (0-100)',
        data: data.map((d) => d.avgHealthScore),
        borderColor: '#6366F1',
        borderWidth: 3,
        pointBackgroundColor: '#6366F1',
        pointBorderColor: '#0A0F1E',
        pointRadius: 4,
        fill: true,
        backgroundColor: (context) => {
          const ctx = context.chart.ctx;
          const gradient = ctx.createLinearGradient(0, 0, 0, 260);
          gradient.addColorStop(0, 'rgba(99, 102, 241, 0.45)');
          gradient.addColorStop(1, 'rgba(99, 102, 241, 0.0)');
          return gradient;
        },
        tension: 0.35,
      },
    ],
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: { display: false },
      tooltip: {
        backgroundColor: '#131B2E',
        titleColor: '#FFFFFF',
        bodyColor: '#94A3B8',
        borderColor: '#1E293B',
        borderWidth: 1,
        padding: 10,
        displayColors: false,
      },
    },
    scales: {
      x: {
        grid: { color: 'rgba(30, 41, 59, 0.4)', drawBorder: false },
        ticks: { color: '#94A3B8', font: { family: 'Plus Jakarta Sans', size: 11 } },
      },
      y: {
        min: 0,
        max: 100,
        grid: { color: 'rgba(30, 41, 59, 0.6)', drawBorder: false },
        ticks: { color: '#94A3B8', font: { family: 'Plus Jakarta Sans', size: 11 }, stepSize: 20 },
      },
    },
  };

  return (
    <div className="glass-card" style={{ padding: '1.5rem', display: 'flex', flexDirection: 'column' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
        <div>
          <h3 style={{ fontSize: '1.05rem', fontWeight: '700', color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <Activity size={18} style={{ color: 'var(--accent-primary)' }} /> Machine Health Trend
          </h3>
          <span style={{ fontSize: '0.78rem', color: 'var(--text-secondary)' }}>7-Day Average Fleet Health Score</span>
        </div>
      </div>
      <div style={{ height: '220px', width: '100%' }}>
        <Line data={chartData} options={options} />
      </div>
    </div>
  );
};

export default HealthTrendChart;
